// Static Business English vocabulary bank.
// Each word is keyed so progress can be tracked in Supabase by word_key.

export type VocabWord = {
  key: string;            // stable kebab-case id
  en: string;
  ka: string;
  explanationKa: string;
  pronunciation: string;  // simple ka phonetic guide
  exampleEn: string;
  exampleKa: string;
  example2En: string;
  example2Ka: string;
  source: "core" | "field";
  week?: number;          // for core words only
  field?: string;         // for field words
  collocations?: { en: string; ka: string }[];  // enrichment (300 core words)
};

