// Spread indices evenly across a week range so words never overflow their
// intended tier (the old `Math.floor(i / 35)` pushed late TIER1 words into
// week 4 → misclassified as tier 2, and late TIER2 words into tier 3).
const spreadWeek = (i: number, len: number, start: number, end: number) =>
  start + Math.min(end - start, Math.floor((i * (end - start + 1)) / Math.max(1, len)));

const CORE_EXTRA: VocabWord[] = [
  ...TIER1.map((m, i) => mk(m, spreadWeek(i, TIER1.length, 1, 3))),   // weeks 1-3
  ...TIER2.map((m, i) => mk(m, spreadWeek(i, TIER2.length, 4, 7))),   // weeks 4-7
  ...TIER3.map((m, i) => mk(m, spreadWeek(i, TIER3.length, 8, 12))),  // weeks 8-12
];

