function enrich(w: VocabWord): VocabWord {
  const e = ENRICHMENT[w.key];
  if (!e) return w;
  return { ...w,
    example2En: e.example2En || w.example2En,
    example2Ka: e.example2Ka || w.example2Ka,
    explanationKa: e.explanationKa || w.explanationKa,
    collocations: e.collocations && e.collocations.length ? e.collocations : w.collocations };
}

export const ALL_WORDS: VocabWord[] = [...CORE_WORDS, ...CORE_EXTRA, ...ALL_FIELD_WORDS].map(enrich);
export const ALL_CORE_WORDS: VocabWord[] = [...CORE_WORDS, ...CORE_EXTRA].map(enrich);

export function findWord(key: string): VocabWord | undefined {
  return ALL_WORDS.find((w) => w.key === key);
}

